import streamlit as st,plotly.graph_objects as go
from src.dashboard.utils.db import _q
st.title('Peer Comparison'); groups=_q('SELECT DISTINCT peer_group_name FROM peer_groups ORDER BY peer_group_name').peer_group_name.tolist()
if not groups: st.info('No peer groups available'); st.stop()
g=st.selectbox('Peer group',groups); df=_q('SELECT pg.company_id,c.company_name,pg.is_benchmark,fr.* FROM peer_groups pg LEFT JOIN companies c ON c.id=pg.company_id LEFT JOIN financial_ratios fr ON fr.company_id=pg.company_id WHERE pg.peer_group_name=?',(g,)); t=st.selectbox('Company',df.company_id.tolist()); row=df[df.company_id==t].iloc[-1]; metrics=['return_on_equity_pct','roce_pct','net_profit_margin_pct','debt_to_equity','free_cash_flow_cr','pat_cagr_5yr','revenue_cagr_5yr','composite_quality_score']; labels=['ROE','ROCE','NPM','D/E','FCF','PAT CAGR','Revenue CAGR','Composite']; vals=[row.get(m) or 0 for m in metrics]; avg=[df[m].median() if m in df else 0 for m in metrics]; fig=go.Figure(); fig.add_trace(go.Scatterpolar(r=vals,theta=labels,fill='toself',name=t)); fig.add_trace(go.Scatterpolar(r=avg,theta=labels,line={'dash':'dash'},name='Peer median')); st.plotly_chart(fig,use_container_width=True); st.dataframe(df,use_container_width=True,hide_index=True)
